let decodeDeadlineExceededError (data: string) : DeadlineExceededError =
    if isNull data || not (data.StartsWith("0x559895a3", StringComparison.OrdinalIgnoreCase)) then invalidArg "data" "Custom error selector mismatch"
    if data.Length <> 10 then invalidArg "data" "Unexpected custom error payload"
    Nethereum.Contracts.Error(typeof<DeadlineExceededError>).DecodeExceptionEncodedData<DeadlineExceededError>(data)

